module TravelCardOptimizer (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] a,\n    input wire [7:0] b,\n    input wire [3:0] k,\n    input wire [15:0] f,\n    input wire [2:0] n,\n    input wire [31:0] stop1,\n    input wire [31:0] stop2,\n    output reg [15:0] total_cost,\n    output reg done\n);\n    \n    // Internal storage for routes\n    reg [31:0] route_start [0:7];\n    reg [31:0] route_end [0:7];\n    reg [15:0] route_cost [0:7];\n    reg [2:0] route_count;\n    \n    // State declarations\n    localparam [3:0] IDLE = 4'd0;\n    localparam [3:0] PROCESS_TRIP = 4'd1;\n    localparam [3:0] UPDATE_ROUTES = 4'd2;\n    localparam [3:0] SORT_INIT = 4'd3;\n    localparam [3:0] SORT_COMPARE = 4'd4;\n    localparam [3:0] SORT_SWAP = 4'd5;\n    localparam [3:0] SORT_NEXT = 4'd6;\n    localparam [3:0] APPLY_CARDS = 4'd7;\n    localparam [3:0] FINISH = 4'd8;\n    \n    reg [3:0] state;\n    reg [2:0] trip_idx;\n    reg [31:0] last_end_stop;\n    reg [31:0] curr_start;\n    reg [31:0] curr_end;\n    reg [15:0] current_cost;\n    reg [2:0] sort_i;\n    reg [2:0] sort_j;\n    reg [2:0] card_idx;\n    reg [15:0] temp_cost;\n    \n    integer i;\n    \n    // Route lookup function\n    function [2:0] find_route;\n        input [31:0] s1, s2;\n        reg [31:0] min_stop, max_stop;\n        integer r;\n        begin\n            min_stop = (s1 < s2) ? s1 : s2;\n            max_stop = (s1 < s2) ? s2 : s1;\n            find_route = 3'd7;\n            for (r = 0; r < route_count; r = r + 1) begin\n                if (route_start[r] == min_stop && route_end[r] == max_stop) begin\n                    find_route = r;\n                end\n            end\n        end\n    endfunction\n    \n    // Bubble sort swap helper\n    task swap_routes;\n        input [2:0] index;\n        begin\n            // Swap route_start\n            route_start[index] <= route_start[index + 1];\n            route_start[index + 1] <= route_start[index];\n            // Swap route_end\n            route_end[index] <= route_end[index + 1];\n            route_end[index + 1] <= route_end[index];\n            // Swap route_cost\n            temp_cost <= route_cost[index];\n            route_cost[index] <= route_cost[index + 1];\n            route_cost[index + 1] <= temp_cost;\n        end\n    endtask\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            total_cost <= 16'd0;\n            route_count <= 3'd0;\n            trip_idx <= 3'd0;\n            last_end_stop <= 32'd0;\n            \n            for (i = 0; i < 8; i = i + 1) begin\n                route_start[i] <= 32'd0;\n                route_end[i] <= 32'd0;\n                route_cost[i] <= 16'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start && n > 0) begin\n                        state <= PROCESS_TRIP;\n                        trip_idx <= 3'd0;\n                        route_count <= 3'd0;\n                        last_end_stop <= 32'd0;\n                        total_cost <= 16'd0;\n                    end\n                end\n                \n                PROCESS_TRIP: begin\n                    curr_start <= stop1;\n                    curr_end <= stop2;\n                    current_cost <= (last_end_stop == 32'd0 || stop1 != last_end_stop) ? {8'd0, a} : {8'd0, b};\n                    state <= UPDATE_ROUTES;\n                end\n                \n                UPDATE_ROUTES: begin\n                    total_cost <= total_cost + current_cost;\n                    \n                    // Find existing route index\n                    reg [2:0] route_idx;\n                    route_idx = find_route(curr_start, curr_end);\n                    \n                    if (route_idx < 3'd7) begin\n                        route_cost[route_idx] <= route_cost[route_idx] + current_cost;\n                    end else if (route_count < 3'd7) begin\n                        if (curr_start < curr_end) begin\n                            route_start[route_count] <= curr_start;\n                            route_end[route_count] <= curr_end;\n                        end else begin\n                            route_start[route_count] <= curr_end;\n                            route_end[route_count] <= curr_start;\n                        end\n                        route_cost[route_count] <= current_cost;\n                        route_count <= route_count + 3'd1;\n                    end\n                    \n                    last_end_stop <= curr_end;\n                    \n                    if (trip_idx < n - 3'd1) begin\n                        trip_idx <= trip_idx + 3'd1;\n                        state <= PROCESS_TRIP;\n                    end else begin\n                        sort_i <= 3'd0;\n                        sort_j <= 3'd0;\n                        state <= SORT_INIT;\n                    end\n                end\n                \n                SORT_INIT: begin\n                    sort_i <= 3'd0;\n                    sort_j <= 3'd0;\n                    state <= SORT_COMPARE;\n                end\n                \n                SORT_COMPARE: begin\n                    if (sort_j < route_count - sort_i - 3'd1) begin\n                        if (route_cost[sort_j] < route_cost[sort_j + 3'd1]) begin\n                            swap_routes(sort_j);\n                        end\n                        sort_j <= sort_j + 3'd1;\n                    end else begin\n                        sort_i <= sort_i + 3'd1;\n                        sort_j <= 3'd0;\n                    end\n                    \n                    if (sort_i >= route_count - 3'd1) begin\n                        card_idx <= 3'd0;\n                        state <= APPLY_CARDS;\n                    end\n                end\n                \n                APPLY_CARDS: begin\n                    if (card_idx < k && card_idx < route_count) begin\n                        if (route_cost[card_idx] > f) begin\n                            total_cost <= total_cost - (route_cost[card_idx] - f);\n                        end\n                        card_idx <= card_idx + 3'd1;\n                    end else begin\n                        state <= FINISH;\n                    end\n                end\n                \n                FINISH: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule